if not os.path.exists(lib):
    open(lib,'w').write('''
def blank(h, w):
    """A h x w grid of zeros."""
    return [[0]*w for _ in range(h)]

def stamp(out, cells):
    """Write (row, col, value) triples onto a grid in order."""
    for r, c, v in cells:
        if 0 <= r < len(out) and 0 <= c < len(out[0]):
            out[r][c] = v
    return out

def overlay(out, cells):
    """Like stamp, but a cell written twice becomes 4 (collision color)."""
    for r, c, v in cells:
        if 0 <= r < len(out) and 0 <= c < len(out[0]):
            out[r][c] = 4 if out[r][c] not in (0, v) else v
    return out

def diagonal_ray(out, r, c, dr, dc, v=4):
    """From the cell after (r, c), paint v along the step (dr, dc) until off-grid."""
    r += dr; c += dc
    while 0 <= r < len(out) and 0 <= c < len(out[0]):
        out[r][c] = v; r += dr; c += dc
    return out

def bar_cells(r, c, length, dr, dc, v):
    """A straight bar of given length from (r, c) stepping (dr, dc): v at both ends, 5 between."""
    return [(r + dr*i, c + dc*i, v if i in (0, length-1) else 5) for i in range(length)]
''')
