DIGITS = {
    1: lambda r, c: bar_cells(r, c, 3, 0, 1, 1) + [(r-1, c+2, 1)],
    2: lambda r, c: bar_cells(r, c, 5, 0, -1, 2),
    3: lambda r, c: bar_cells(r, c, 4, 1, 0, 3),
    6: lambda r, c: bar_cells(r, c, 7, -1, 0, 6),
}

def transform(grid):
    out = blank(len(grid), len(grid[0]))
    cells = [cell for r, row in enumerate(grid) for c, v in enumerate(row)
             if v and (cell := DIGITS[v](r, c))]
    overlay(out, [x for cell in cells for x in cell])
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v in DIGITS:
                pass
    # rays from crossing cells
    seen = {}
    for cell in cells:
        for r, c, v in cell:
            seen[(r, c)] = seen.get((r, c), 0) + 1
    for (r, c), n in seen.items():
        if n > 1:
            diagonal_ray(out, r, c, 1, -1, 4)
    return out
''')
